foreach($p in @('English/characters/ganyu.json','ChineseSimplified/talents/ganyu.json','ChineseSimplified/constellations/ganyu.json')){
  Write-Output ("===== $p =====")
  (curl.exe -s -x htt./ --max-time 30 "$b/$p")
}"}

