content.arguments:
{"description":"Fetch xiao/hutao/yelan constellations and probe talent params","command":"$ProgressPreference='SilentlyContinue'
$b='http./'
foreach($c in @('xiao','hutao','yelan')){
  $raw = curl.exe -s -x htt./ --max-time 30 "$b/ChineseSimplified/constellations/$c.json"
  try { $j = $raw | ConvertFrom-Json } catch { Write-Output "=== $c FETCH FAIL ==="; continue }
  Write-Output "=== $c ($($j.name)) ==="
  foreach($k in 1..6){
    $o = $j."c$k"
    $d = ($o.description -replace "`r?`n",' ')
    Write-Output ("c{0} {1} :: {2}" -f $k, $o.name, $d)
  }
}
$t = (curl.exe -s -x htt./ --max-time 30 "$b/English/talents/ganyu.json") | ConvertFrom-Json
Write-Output "=== ganyu EN combat1 attributes ==="
Write-Output ($t.combat1.attributes | ConvertTo-Json -Depth 6 -Compress)"}

