content.arguments:
{"description":"List gcsim ganyu dir and read ganyu.go","command":"$ProgressPreference='SilentlyContinue'
$api='http./'
try{
 $j = (curl.exe -s -x htt./ --max-time 30 $api) | ConvertFrom-Json
 Write-Output ("FILES: " + (($j | ForEach-Object { $_.name }) -join ', '))
}catch{ Write-Output "API FAIL" }
Write-Output '--- ganyu.go ---'
curl.exe -s -x htt./ --max-time 30 'http./'"}

